            criteria[cand] = "the request is really about " + cand
        criteria["none"] = "none of these ids should be used"

        state = {"request": text, "kind": kind, "candidates": cands}
        asked = await kit.ask(
            state,
            {
                "pick": {
                    "type": "choice",
                    "instructions": "Choose the likeliest " + kind + " id the user means. If none of the candidates fits, choose none.",
                    "criteria": criteria,
                }
            },
        )
        choice = asked["pick"]["choice"]
        if choice == "none":
            return None
        if choice in cands:
            return choice
        return None

    has_cancel = any(word in lower for word in CANCEL_WORDS)
    has_payment_status = ("payment" in lower and ("status" in lower or "scheduled" in lower or "scheduled yet" in lower))
    has_doc_status = (
        "document" in lower
        and ("entered yet" in lower or "been entered" in lower or "has document" in lower or "already entered" in lower)
    )
    has_enter = any(word in lower for word in ENTER_WORDS)
    has_schedule = any(word in lower for word in SCHEDULE_WORDS)
    has_amount = any(word in lower for word in AMOUNT_WORDS)
