        parsed = await kit.procedure("parse_invoice", doc_id=doc_id)
        if not isinstance(parsed, dict) or parsed.get("error"):
            return {"handoff": "I couldn't parse document " + doc_id + " for ledger entry."}
        required = ["doc_id", "invoice_number", "po_number", "invoice_date", "subtotal_usd", "freight_usd", "discount_percent", "discount_days", "net_days"]
        if not all(key in parsed for key in required):
            return {"handoff": "Document " + doc_id + " is missing required invoice fields."}
        args = {
            "doc_id": parsed["doc_id"],
            "invoice_number": parsed["invoice_number"],
            "po_number": parsed["po_number"],
            "invoice_date": parsed["invoice_date"],
            "subtotal_usd": clean_number(parsed["subtotal_usd"]),
            "freight_usd": clean_number(parsed["freight_usd"]),
            "discount_percent": clean_number(parsed["discount_percent"]),
            "discount_days": clean_number(parsed["discount_days"]),
            "net_days": clean_number(parsed["net_days"]),
        }
        return {
            "action": "record_invoice",
            "arguments": args,
            "reply": "Recorded " + doc_id + " in the ledger."
