    low = text.lower()
    for word in words:
        if word in low:
            return True
    return False


def extract_digits(match):
    out = ""
    for ch in str(match):
        if "0" <= ch <= "9":
            out += ch
    return out


def extract_trip_ids(text, kit):
    found_ids = []
    for pattern in TRIP_PATTERNS:
        matches = kit.find(pattern, text)
        for match in matches:
            trip_id = extract_digits(match)
            if trip_id != "" and trip_id not in found_ids:
                found_ids.append(trip_id)
    return found_ids


