DOC_PATTERNS = ["DOC[ -]?[0-9]+", "DOCUMENT[ -]?[0-9]+"]
INV_PATTERNS = ["INV[ -]?[0-9]+", "INVOICE[ -]?[0-9]+"]
WINDOW = 35

async def decide(request, kit):
    req = request.upper().replace("’", "'").replace("“", '"').replace("”", '"')

    def digits(text):
        out = ""
        for ch in text:
            if ch >= "0" and ch <= "9":
                out = out + ch
        return out

    def addMatch(store, key, raw):
        if key == "":
            return
        if key not in store:
            store[key] = []
        if raw not in store[key]:
            store[key].append(raw)

    def scan(patterns, prefix):
        store = {}
        for pat in patterns:
            found = kit.find(pat, req)
            for raw in found:
                d = digits(raw)
                if d != "":
                    addMatch(store, prefix + "-" + d, raw)
        return store

    docMap = scan(DOC_PATTERNS, "DOC")
    invMap = scan(INV_PATTERNS, "INV")

    def docScore(raws):
        score = 0
        for raw in raws:
            pos = req.find(raw)
            while pos != -1:
                start = pos - WINDOW
                if start < 0:
                    start = 0
                end = pos + len(raw) + WINDOW
                if end > len(req):
                    end = len(req)
                win = req[start:end]
                if (("ENTER" in win or "RECORD" in win or "ADD" in win) and ("LEDGER" in win or "VENDOR INVOICE" in win)):
                    score = score + 3
                pos = req.find(raw, pos + 1)
        return score

    def invScore(raws):
        score = 0
        for raw in raws:
            pos = req.find(raw)
            while pos != -1:
                start = pos - WINDOW
                if start < 0:
                    start = 0
                end = pos + len(raw) + WINDOW
                if end > len(req):
                    end = len(req)
                win = req[start:end]
                if (("SCHEDULE" in win or "SET UP" in win) and "PAYMENT" in win):
                    score = score + 3
                pos = req.find(raw, pos + 1)
        return score

    async def choose(store, kind):
        keys = []
        for key in store:
            keys.append(key)
        if len(keys) == 0:
            return ""
        scored = []
        maxScore = 0
        for key in keys:
            raws = store[key]
            if kind == "document":
                sc = docScore(raws)
            else:
                sc = invScore(raws)
            scored.append((key, sc))
            if sc > maxScore:
                maxScore = sc
        if maxScore <= 0:
            return ""
        top = []
        for item in scored:
            if item[1] == maxScore:
                top.append(item[0])
