    "unfiled",
    "don't file",
    "dont file",
    "do not file",
    "not file",
]

def hasAny(text, items):
    for item in items:
        if item in text:
            return True
    return False

async def decide(request, kit):
    text = request.lower()

    if hasAny(text, BLOCK_WORDS):
        return {"handoff": "request is not a straightforward claim-filing request"}

    if not hasAny(text, FILE_WORDS):
        return {"handoff": "request does not clearly ask to file an expense claim"}

    ids = kit.find("T-[0-9]+", request)
    if len(ids) == 0:
        return {"handoff": "no canonical trip id found"}

    tripid = ids[0]

    if len(ids) > 1:
        questions = {
            "trip_id": {
                "type": "choice",
                "instructions": "Choose the single trip id the user wants filed. If the request is not clearly asking to file exactly one expense claim, choose none.",
                "criteria": dict([(x, "file this trip") for x in ids] + [("none", "no single trip should be filed")]),
            }
        }
        judged = await kit.ask({"request": request, "trip_ids": ids}, questions)
        answer = judged["trip_id"]
        if answer["choice"] == "none" or answer["choice"] not in ids or answer["confidence"] < 0.75:
            return {"handoff": "could not determine the trip id confidently"}
        tripid = answer["choice"]

    trip = kit.read("read_trip", trip_id=tripid)
    if not isinstance(trip, dict) or "error" in trip:
        return {"handoff": "trip id was not found"}

    total = await kit.procedure("reimbursable_total", trip_id=tripid)
    if not isinstance(total, dict) or "total_usd" not in total:
        return {"handoff": "could not compute reimbursable total"}

    amount = round(float(total["total_usd"]), 2)

    return {
        "action": "file_claim",
        "arguments": {"trip_id": tripid, "amount_usd": amount},
        "reply": "I’m filing your expense claim for " + tripid + ".",
    }
