FILE_WORDS = ("file", "submit")
BAD_WORDS = ("status", "cancel", "split", "estimate", "policy", "allowance", "wrong", "change", "modify", "update")

async def decide(request, kit):
    text = request.lower()

    if any(word in text for word in BAD_WORDS):
        return {"handoff": "This request is not clearly a claim filing request."}

    raw_ids = kit.find("[Tt]-[0-9]+", request)
    ids = []
    seen = set()
    for raw in raw_ids:
        trip_id = raw.upper()
        if trip_id not in seen:
            seen.add(trip_id)
            ids.append((trip_id, raw))

    if len(ids) == 0:
        return {"handoff": "No clear trip id was provided for filing a claim."}

    file_intent = False
    if "file" in text or "submit" in text:
        file_intent = True
    elif "expense claim" in text and ("please" in text or "could you" in text or "can you" in text):
        file_intent = True

    if not file_intent:
        return {"handoff": "This request is not clearly asking to file a claim."}

    def score_candidate(raw):
        pos = request.find(raw)
        if pos < 0:
            return -999
        left = text[max(0, pos - 45):pos]
        right = text[pos + len(raw):min(len(text), pos + len(raw) + 45)]
        window = left + right
        score = 0
        if "expense claim" in window:
            score += 5
        if "file" in window:
            score += 4
        if "submit" in window:
            score += 4
        if "please" in window:
            score += 1
        if "only" in window:
            score += 1
        if "claim" in window:
            score += 1
        if "other" in window:
            score -= 3
        if "different" in window:
            score -= 4
        if "ignore" in window:
            score -= 4
        if "needs nothing" in window:
            score -= 4
        if "no claim" in window:
            score -= 4
        if "not" in left[-12:]:
            score -= 3
        return score

    best = None
    best_score = -999
    tied = False

    if len(ids) == 1:
        best = ids[0][0]
    else:
        for trip_id, raw in ids:
            score = score_candidate(raw)
            if score > best_score:
                best_score = score
                best = trip_id
                tied = False
            elif score == best_score:
                tied = True
        if best is None or best_score <= 0 or tied:
            return {"handoff": "I can't confidently determine which trip to file."}

    trip = None
    for tool in ("read_trip", "trip"):
        try:
            trip = kit.read(tool, trip_id=best)
        except Exception:
            trip = None
        if isinstance(trip, dict) and "error" not in trip:
            break
        trip = None

    if trip is None:
        return {"handoff": "I couldn't verify that trip id."}

    total = None
    try:
        total = await kit.procedure("reimbursable_total", trip_id=best)
    except Exception:
        total = None

    if not isinstance(total, dict) or "total_usd" not in total:
        return {"handoff": "I couldn't compute the reimbursable total."}

    amount = round(float(total["total_usd"]), 2)
    return {
        "action": "file_claim",
        "arguments": {"trip_id": best, "amount_usd": amount},
        "reply": "Filing your expense claim for " + best + "."
    }
