TRIPPATTERN = "[Tt][Rr][Ii][Pp][ -]*[0-9][0-9]?[0-9]?|[Tt][ -]*[0-9][0-9]?[0-9]?"
MINCONFIDENCE = 0.8

async def decide(request, kit):
    def digits(text):
        out = ""
        for ch in str(text):
            if ch >= "0" and ch <= "9":
                out = out + ch
        return out

    def asint(text):
        num = digits(text)
        if len(num) == 0:
            return None
        try:
            return int(num)
        except Exception:
            return None

    def sameid(left, right):
        leftnum = asint(left)
        rightnum = asint(right)
        if leftnum is not None and rightnum is not None:
            return leftnum == rightnum
        return str(left) == str(right)

    def verifytrip(data, wanted):
        if isinstance(data, dict):
            if "error" in data and data["error"]:
                return False
            for key in data:
                low = str(key).lower()
                if "trip" in low or low == "id":
                    if sameid(data[key], wanted):
                        return True
            return False
        return sameid(data, wanted)

    raw = kit.find(TRIPPATTERN, request)
    tripTexts = []
    for item in raw:
        num = digits(item)
        if len(num) > 0 and num not in tripTexts:
            tripTexts.append(num)

    if len(tripTexts) == 0:
        return {"handoff": "I couldn't identify one trip to file."}

